function rankHP(currentHP){
    if(currentHP % 4 == 1){
        return(1);
    } else if(currentHP % 4 == 3) {
        return(3);
    } else if (currentHP % 4 == 2) {
        return(2);
    } else if (currentHP % 4 == 0) {
        return(0);
    }
}

function rankAchievedToLetter(rankAchieved){
    if(rankAchieved == 1){
        return(' A');
    } else if(rankAchieved == 3) {
        return(' B');
    } else if (rankAchieved == 2) {
        return(' C');
    } else if (rankAchieved == 0) {
        return(' D');
    }
}

function getResult(hp){
    let ranks = [0,0,0];
    let rankAchieved = rankHP(hp);
    if (rankAchieved == '1'){
        return 0 + rankAchievedToLetter(rankAchieved);
    } else {
        ranks = [rankAchieved, rankHP(hp+1), rankHP(hp+2)];
        //console.log(ranks);
        if (ranks.includes(1)){
            obama = rankHP(ranks[ranks.indexOf(1)]);
            //console.log(obama);
            return (hp+ranks.indexOf(1)) + rankAchievedToLetter(obama);
        } else {
            obama = ranks[ranks.indexOf(Math.max(...ranks))];
            //console.log(obama);
            return (hp+ranks.indexOf(Math.max(...ranks))) + rankAchievedToLetter(obama);
        };

    };
};

rl.question('', (answer) => {
    hp = answer;
    //console.log('hp', hp, typeof hp);
    console.log(getResult(parseInt(hp)));
    process.exit();
});

