function solve(n, ar) {
    ar.sort((a, b) => a - b);
    let ans = (ar[n - 1] - ar[0]) % 2 === 0 ? (ar[n - 1] - ar[0]) / 2 : -1;
    for (let i = 0; i < n; i++) {
        if (ar[i] !== ar[0] && ar[i] !== ar[n - 1] && ar[i] !== ar[0] + ans) ans = -1;
    }
    return ans;
}

