function pangram(stringLength, word) {

    let alphabet = 'abcdefghijklmnopqrstuvwxyz'.split('');
    let stringToMap = {};
    let occurance = {};
    word = word.toLowerCase();

    for (let index = 0; index < stringLength; index++) {
        stringToMap[word[index]] = 1;
    }

    for (let index = 0; index < alphabet.length; index++) {
        if (stringToMap[alphabet[index]])
            occurance[alphabet[index]] = 1
    }

    if(Object.keys(occurance).length == alphabet.length)
      return 'YES';

    return 'NO';
}

