        m[c] = false;
    }
    str.split('').forEach(letter => {
        m[letter.charCodeAt(0)] = true;
    });
    for (var key in m) {
        if (m.hasOwnProperty(key) && m[key] === false) {
            return "NO\n";
        }
    }
    return "OK\n";
}

