// Return the charcter position
function charPosition(char) {
    let low = 0
    let high = chars.length - 1
    let mid = Math.floor((low + high) / 2)


    while (low <= high) {
        mid = Math.floor((low + high) / 2)
        if (chars.indexOf(char) > mid)
            low = mid + 1
        else if (chars.indexOf(char) < mid)
            high = mid - 1
        else
            return mid
    }

    return -1
}

// Recognize which one's order is greater than the other
function recognize(fWord, sWord) {

    for (let i = 0; i < fWord.length; i++) {
        const char1 = fWord[i].toLowerCase();
        const char2 = sWord[i].toLowerCase();

        if (charPosition(char1) > charPosition(char2))
            return console.log(1);
        else if (charPosition(char1) < charPosition(char2))
            return console.log(-1);
    }


    return console.log(0)
}

