function main() {
  const is = new Scanner();
  const [n, m] = is.nextArray().map(Number);
  const word = is.nextLine().split('');
  word.forEach((item, index, array) => {
    array[index] = item.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
  });
  word.sort((a, b) => a - b);

  let answer = Infinity;

  function calc(i, accum, number) {
    if (number === m) {
      answer = Math.min(answer, accum);
    }
    if (i === n || number > m) {
      return;
    }

    if (Math.abs(word[i] - word[i + 1]) >= 2) {
      calc(i + 1, accum + word[i + 1], number + 1);
    }
    calc(i + 1, accum, number);
  }

  calc(0, word[0], 1);
  console.log(answer === Infinity ? -1 : answer);
}

