const getPrimes = () => {
  const maxN = 25;
  const arr = new Array(maxN + 1).fill(1);
  arr[0] = 0;
  arr[1] = 0;

  for (let i = 2; i*i <= maxN; i++) {
    if (arr[i]) {
      for (let j = i*i; j <= maxN; j += i) {
        arr[j] = 0;
      }
    }
  }

  const primes = [];

  for (let i = 0; i < arr.length; i++) {
    if (arr[i]) {
      primes.push(i);
    }
  }

  return primes;
}

