function totalCriminalCatch(totalCities, a, ti) {

    ti = ti.map(Number);
    let count = 0;

    for (var i = 0; i < 100; i++) {

        let a1 = (a - 1 - i >= 0 && ti[a - 1 - i] > 0) || a - 1 - i < 0;
        let a2 = (a - 1 + i < totalCities && ti[a - 1 + i] > 0) || a - 1 + i > totalCities

        if (a1 && a2) {
            if (i == 0) {
                count += 1;
            } else {

                if ((a - 1 - i >= 0 && ti[a - 1 - i] > 0)) {
                    count++;
                }

                if ((a - 1 + i < totalCities && ti[a - 1 + i] > 0)) {
                    count++;
                }
            }
        }
    }

    return count;
}

