function minTiles(arr) {
  const set = new Set([...arr]);
  if (set.size === 1) return 0;
  if (set.size === 2) return 1;

  let min = 2;
  set.forEach(tile => {
    if (set.has(`${Number(tile.split('')[0]) + 1}${tile.split('')[1]}`)) {
      if (set.has(`${Number(tile.split('')[0]) + 2}${tile.split('')[1]}`)) {
        min = 0;
      } else {
        min = Math.min(min, 1);
      }
    }
  });

  return min;
}

