function getNumberOfCrossedThreshold(arr, cutOffIndex) {
  // Check if the cutoff Indey should be less than array length;
  // array length should be of 1 length;
  const cutOff = arr[cutOffIndex];
  return arr.reduce((acc, curr) => {
    if (Number(curr) >= Number(cutOff)) {
      ++acc;
    }

    return acc;
  }, 0);
}

