        let rem = n - firstTriangle;

        if(rem === 0) continue;

        let secFactor = maxTrianglePossible(rem);
        let secTriangle = triangleNumbers(secFactor);

        let triangles = firstTriangle + secTriangle;

        if(triangles == n) {
            funkyNumber = 'YES';
            break;
        } 

    }

    return funkyNumber; 
}

