function minOperations(nums, k) {
  nums = nums.sort((a, b) => a - b);

  let totalMin = Number.MAX_VALUE;
  for (let i = -1; i <= nums.length - k; i++) {
    if (i > 0 && nums[i] === nums[i - 1]) continue;

    let index;
    let numToMake;

    if (i === -1) {
      index = 0;
      numToMake = 1;
    } else {
      index = i;
      numToMake = nums[index];
    }

    let operations = 0;
    let matches = 0;
    while (index < nums.length) {
      let currNumber = nums[index];
      let currOperations = 0;
      while (currNumber > numToMake) {
        currNumber = Math.floor(currNumber / 2);
        currOperations++;
      }
      if (currNumber === numToMake) {
        matches++;
        operations += currOperations;
      }

      if (matches === k) {
        totalMin = Math.min(operations, totalMin);
        break;
      }
      index++;
    }
  }
  return totalMin;
}

