    let closest = ''
    while (true) { 
        if (n <= 9) {
			closest = n + closest
			break
        }

		closest = 9 + closest
        n = ~~((n - 9) / 10)
    }

    return Number(closest)
  }

  function nirvana (n) {
    const c = closest(n)
    const sC = String(c).split('')
    let grtst = Number(sC.reduce((i, acc = 1) => Number(i) * acc))

    for (let i = c + 1; i <= n; i++) {
    const sI = String(i).split('')
        let dMult = Number(sI.reduce((i, acc = 1) => i * acc))
        grtst = dMult > grtst ? dMult : grtst
    }

    return grtst
  }

  console.log(nirvana(n))
})

