  let first = 0, second = 0, copyN = n;
  let point = (m % 2 === 0) ? m : m + 1;

  while (copyN !== point/2) {
    if (copyN > point/2) {
      first += copyN - (point/2);
      copyN = point/2;
    }
    if (copyN < point/2) { copyN *= 2;  first += 1; }
  }
  first += (m % 2 === 0) ? 1 : 2;

  copyN = n;
  while (copyN !== m) {
    if (copyN < m) copyN *= 2;
    else {
