function logic() {
    const line = readline();

    const params = line.split(' ');
    const number = parseInt(params[0]);
    const iterations = parseInt(params[1]);

    let result = number;
    for (let i=1; i <= iterations; i++) {
        let lastNum = parseInt(String(result)[result.length-1]);
        if (lastNum > 0) {
            result--;
        }
        else {
            result /= 10;
        }
    }

    output(result);
}

