function solve(a, b) {
 if (a == b) { console.log(0); return; }

 const m = {}
 if (b > a) {
  const t = a; a = b; b = t;
 }
 const ma = { [a]: 0 }
 const mb = { [b]: 0 }

 const qa = [[a, 0]]
 const qb = [[b, 0]]

 let min = Infinity;
 while (true) {
  if (qa.length) {
  const [aa, sa] = qa.shift()

  for (const d of [2,3,5]) {
   if (aa%d == 0) {
     const r = aa/d
     if (mb[r]) { min = Math.min(mb[r]+sa+1, min); } 
     if (!ma[r]) { qa.push([r, sa+1]) }
     ma[r] = ma[r] || (sa+1); 
   }
  }
 }

 if (qb.length) {

  const [bb, sb] = qb.shift()
  for (const d of [2,3,5]) {
   if (bb%d == 0) {
     const r = bb/d
     if (ma[r]) { min = Math.min(ma[r]+sb+1, min); }
     if (!mb[r]) { qb.push([r, sb+1]) }
     mb[r] = mb[r] || (sb+1);
   }
  }
 }

 if (isFinite(min)) { console.log(min); return; }

  if (!qa.length && !qb.length) { console.log(-1); return; }

 }
}

