                        op += t[j]
                        i = j
                    }
                    else
                        break
                }
                opVariables.push(op)
                op = ''
            } else {
                if ( i == 0 || (i>0 && isOp(t[i-1])) ) {
                    op = t[i]
                    let j = i + 1
                    for(; j<t.length; j++) {
                        if ( isInt(t[j]) ) {
                            op += t[j]
                            i = j
                        }
                        else
