function findMax(n) {
	var digits = ("" + n).split(""),
		currentSum = getDigitsSum(digits),
		nextNumber = +((digits[0] - 1) + (new Array(digits.length)).join("9")),
		nextSum = getDigitsSum(nextNumber);

	if(currentSum > nextSum) return n;
	if(currentSum < nextSum) return nextNumber;
	return Math.max(n, nextNumber);
}

function getDigitsSum(digits) {
	if(!Array.isArray(digits)) digits = ("" + digits).split("");
	return digits.reduce(function (sum, n) {
		return sum + 1*n;
	}, 0);
}

