function nameLookUp(str) {
    let frnLocation = str.trim();
    let moves = [1, 2, 3, 4, 5];
    let steps = stepsToTake(moves, +frnLocation);
    return steps.toString();
}

function stepsToTake(moves = [], frnLocation, steps = 0) {

    let newNum = 1;
    for (let row of moves) {
        if (row < frnLocation) {
            newNum = row;
        }
    }

    frnLocation = frnLocation - newNum;
    if (frnLocation !== 0) {
        steps++;
        return stepsToTake(moves, frnLocation, steps);
    }
    else {
        return steps;
    }
}

