function solution(lengthOfString, string) {

    let onesCount = 0;
    let zeorCount = '';
    let digit = [];

    for (let index = 0; index < lengthOfString; index++) {

        if (string[index] == '1') {

            onesCount++;

            if (zeorCount.length > 1)
                digit.push(zeorCount.substring(0, zeorCount.length - 1));

